/*
 * {{NAME}} — v1 Express server.
 *
 * Generated by create-innology-app. Consumes @innologybd/core for the CSP
 * preset, security headers, and the typed auth guard — nothing is re-implemented.
 */

import express from "express";
import cookieParser from "cookie-parser";
import { z } from "zod";
import {
  securityHeaders,
  rpcGuard,
  validateSession,
  authGuard,
  requireRole,
} from "innologybd-core";
import { makeSession } from "innologybd-core/auth";

const app = express();
const PORT = process.env.PORT ? Number(process.env.PORT) : 3001;

app.use(cookieParser());
app.use(express.json());
app.use(securityHeaders());

/* ---- auth: dev login issues a signed session cookie ---- */
app.post("/login", (_req, res) => {
  res.cookie(
    "v1_session",
    makeSession("00000000-0000-0000-0000-000000000001", "user"),
    { httpOnly: true, sameSite: "lax", maxAge: 1000 * 60 * 60 * 24 },
  );
  res.json({ ok: true });
});

app.post("/logout", (_req, res) => {
  res.clearCookie("v1_session");
  res.json({ ok: true });
});

/* ---- server functions: every /rpc/* route is auth-guarded ---- */
app.post(
  "/rpc/getMessage",
  rpcGuard(validateSession, authGuard),
  (_req, res) => {
    res.json({ ok: true, text: "Hello from {{NAME}} server function." });
  },
);

app.post(
  "/rpc/getProfile",
  rpcGuard(validateSession, authGuard),
  (_req, res) => {
    res.json({ ok: true, name: "{{NAME}} user", role: "user" });
  },
);

/* ---- role-guarded route: admin only ---- */
app.post(
  "/rpc/getAdminMessage",
  rpcGuard(validateSession, requireRole("admin")),
  (_req, res) => {
    res.json({ ok: true, text: "Admin-only data." });
  },
);

/* ---- validated route: 422 on bad input ---- */
const InputSchema = z.object({ name: z.string().min(1) });
app.post(
  "/rpc/validateInput",
  rpcGuard(validateSession, authGuard),
  (req, res) => {
    const parsed = InputSchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(422).json({ error: "Invalid input", issues: parsed.error.issues });
      return;
    }
    res.json({ ok: true, name: parsed.data.name });
  },
);

app.use("/rpc/*", (_req, res) => {
  res.status(404).json({ error: "Server function not found" });
});

app.get("/health", (_req, res) => res.json({ ok: true }));

app.listen(PORT, () => {
  console.log(`{{NAME}} listening on http://localhost:${PORT}`);
});